import { useLiveQuery } from '@tanstack/vue-db'
import { quotesCollection } from '../../data/quotes.collection'

/** Query "Latest quotes": the first `limit` quotes from the quotes data source. */
export const useLatestQuotes = (limit = 3) =>
  useLiveQuery(q => q
    .from({ quote: quotesCollection })
    .orderBy(({ quote }) => quote.id, 'asc')
    .limit(limit)
  )
